def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Merge intervals
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # No overlap, add new interval
            merged.append([current_start, current_end])

    return merged

def toposort(nodes, edges):
    # Build adjacency list and in-degree count
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Process edges to build graph and count in-degrees
    edge_set = set()  # To handle duplicate edges
    for source, dest in edges:
        if source == dest:
            raise ValueError("Cycle detected (self loop)")
        if (source, dest) not in edge_set:
            graph[source].append(dest)
            in_degree[dest] += 1
            edge_set.add((source, dest))

    # Initialize queue with nodes having zero in-degree
    queue = []
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    # Sort to ensure lexicographically smallest order
    queue.sort()

    result = []

    while queue:
        # Choose the lexicographically smallest node
        current = queue.pop(0)
        result.append(current)

        # Process neighbors
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
                queue.sort()  # Keep sorted for lexicographic choice

    # Check if all nodes were included (cycle detection)
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("Limit must be positive")

    result = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("Weights must be positive and not exceed the limit")

        if current_weight + weight > limit:
            if current_batch:
                result.append(current_batch)
            current_batch = []
            current_weight = 0

        current_batch.append(name)
        current_weight += weight

    if current_batch:
        result.append(current_batch)

    return result

def parse_sse(chunks):
    buffer = ""
    events = []
    current_event = {}

    for chunk in chunks:
        buffer += chunk.decode('utf-8')

        while '\n' in buffer:
            line_end = buffer.find('\n')
            line = buffer[:line_end]
            buffer = buffer[line_end + 1:]

            # Handle CRLF
            if line.endswith('\r'):
                line = line[:-1]

            if not line:
                # Blank line - dispatch event
                if 'data' in current_event:
                    events.append(current_event['data'])
                current_event = {}
                continue

            if line.startswith(':'):
                # Comment - ignore
                continue

            # Parse field
            if ':' in line:
                field, value = line.split(':', 1)
                if value and value[0] == ' ':
                    value = value[1:]
            else:
                field = line
                value = ""

            if field == 'data':
                if 'data' not in current_event:
                    current_event['data'] = value
                else:
                    current_event['data'] += '\n' + value

    # Handle final event if it's complete and not [DONE]
    if 'data' in current_event and current_event['data'] != '[DONE]':
        events.append(current_event['data'])

    # Remove unterminated final event
    if len(events) > 0:
        if events[-1] == '[DONE]':
            return events[:-1]

    return events

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("All arguments must be nonnegative")

    if attempt >= 30:  # 2^30 is already very large, prevents overflow
        if base == 0:
            return float(0.0)
        else:
            return cap

    # Calculate base * 2**attempt without constructing huge integers
    # We'll use the fact that 2**30 is about 1 billion, so we can safely compute up to 2^30
    if attempt >= 30:
        result = base * (2 ** 30)  # This will be a very large number
        # But since we're comparing with cap, and cap could be finite, let's handle it carefully
        for i in range(30, attempt):
            if result > float('inf') or result > cap:
                return cap
            result *= 2
        return min(cap, result)

    # For smaller attempts, compute directly
    # Handle case where base = 0
    if base == 0:
        return float(0.0)

    # Use the built-in pow function to avoid integer overflow issues
    try:
        # This handles the computation safely
        delay = base * (2 ** attempt)
        return min(cap, delay)
    except OverflowError:
        # If we get an overflow, return cap since it's already too large
        return cap

def fifo_admit(active, queued, budget, slots):
    # Check if any queued reservation exceeds the whole budget
    for reservation in queued:
        if reservation > budget:
            raise ValueError("Queued reservation exceeds budget")

    # Initialize result lists
    admitted = []
    remaining = []

    # Track current usage
    active_tokens = sum(active)
    active_slots = len(active)

    # Process queued requests in FIFO order
    for request in queued:
        if active_slots < slots and active_tokens + request <= budget:
            # Admit the request
            admitted.append(request)
            active_tokens += request
            active_slots += 1
        else:
            # Reject the request
            remaining.append(request)

    return (admitted, remaining)
